 public new void DrawToBitmap(Bitmap bmp, Rectangle rect) {            Console.WriteLine("ShapeNgon > DrawToBitmap > bmp:{0}", bmp);            using (var g = Graphics.FromImage(bmp)) {                using (var brush = new SolidBrush(BackColor)) {                    var region = new Region(graphicsPathOuter);                    if (BorderSize > 0) region.Exclude(graphicsPathInner);                    g.FillRegion(brush, region);                }                using (Pen pen = new Pen(BorderColor, BorderSize)) {                    if (BorderSize > 0) {                        if (BorderType != OutlineStyle.Plná) {                            pen.DashStyle = Translate.GetDashStyle(BorderType);                        }                        g.DrawPath(pen, graphicsPathOuter);                        g.DrawPath(pen, graphicsPathInner);                    } else {                        g.DrawPath(pen, graphicsPathOuter);                    }                }            }        }        internal override Image AsImage() {            Bitmap bitmap = new Bitmap(Width, Height, PixelFormat.Format32bppArgb);            using (var g = Graphics.FromImage(bitmap)) {                using (var brush = new SolidBrush(BackColor)) {                    var region = new Region(graphicsPathOuter);                    if (BorderSize > 0) region.Exclude(graphicsPathInner);                    g.FillRegion(brush, region);                }                using (Pen pen = new Pen(BorderColor, BorderSize)) {                    if (BorderSize > 0) {                        if (BorderType != OutlineStyle.Plná) {                            pen.DashStyle = Translate.GetDashStyle(BorderType);                        }                        g.DrawPath(pen, graphicsPathOuter);                        g.DrawPath(pen, graphicsPathInner);                    } else {                        g.DrawPath(pen, graphicsPathOuter);                    }                }            }            return bitmap;        }        public static Image GetControlSnapshot(Control control) {            Bitmap image = new Bitmap(control.Bounds.Width, control.Bounds.Height);            using (Graphics g = Graphics.FromImage(image)) {                g.CopyFromScreen(                    control.Parent.PointToScreen(new Point(control.Left, control.Top)),                    new Point(0, 0),                    new Size(control.Bounds.Width, control.Bounds.Height));            }            return image;        }        // Create image from a control         public static Image DrawToBitmap(Control control) {            Bitmap b = new Bitmap(control.Width, control.Height, PixelFormat.Format32bppArgb);            control.DrawToBitmap(b, control.ClientRectangle);            return b;        }